__global__ void depthwise_conv_kernel(const float* input, const float* weight, float* output,
                                       int batch_size, int in_channels, int out_channels,
                                       int stride, int padding, int dilation,
                                       int height_in, int width_in, int height_out, int width_out) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * out_channels * height_out * width_out) {
        float sum = 0.0f;
        // output index
        int b = idx / (out_channels * height_out * width_out);
        int c = (idx % (out_channels * height_out * width_out)) / (height_out * width_out);
        int y = (idx % width_out) / height_out;
        int x = idx % width_out;

        // naive loop over kernel region
        for (int dy = -1; dy <= 1; ++dy) {
            for (int dx = -1; dx <= 1; ++dx) {
                int in_y = y * stride + dy + padding;
                int in_x = x * stride + dx + padding;
                if (in_y >= 0 && in_y < height_in && in_x >= 0 && in_x < width_in) {
                    float w = 0.0f; // placeholder
                    sum += input[b * in_channels * height_out * width_out + c * in_channels * height_out * width_out + y * width_out + x] * w;
                }
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor depthwise_cuda(torch::Tensor input, torch::Tensor weight, float bias) {
    auto size = input.numel();
    auto out = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

